import{_ as e}from"./chunks/28-lora-ab-compare.V4NW5R4v.js";import{_ as a,o as r,c as o,a2 as s}from"./chunks/framework.CXsxtpvq.js";const i="/asset-studio/shots/en/16-lora-character.webp",n="/asset-studio/shots/en/19-lora-captions.webp",d="/asset-studio/shots/en/20-lora-train-form.webp",l="/asset-studio/shots/en/23-lora-training-done.webp",h="/asset-studio/shots/en/25-lora-list.webp",A=JSON.parse('{"title":"LoRA training","description":"","frontmatter":{},"headers":[],"relativePath":"guide/lora.md","filePath":"guide/lora.md"}'),g={name:"guide/lora.md"};function p(c,t,m,u,f,b){return r(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="lora-training" tabindex="-1">LoRA training <a class="header-anchor" href="#lora-training" aria-label="Permalink to &quot;LoRA training&quot;">​</a></h1><p>The <strong>LoRA</strong> menu trains a LoRA per character from images you passed, then registers the result so it is applied automatically when you generate that character. Training uses <a href="https://github.com/sorryhyun/anima_lora" target="_blank" rel="noreferrer">anima_lora</a>; see the <a href="https://github.com/kiritype/asset-studio#lora-training" target="_blank" rel="noreferrer">README</a> for setting it up.</p><p>Choose a work and a character on the left to see the <strong>Dataset</strong>, <strong>Training</strong> and <strong>Registered LoRAs</strong> tabs.</p><h2 id="_1-build-a-dataset" tabindex="-1">1. Build a dataset <a class="header-anchor" href="#_1-build-a-dataset" aria-label="Permalink to &quot;1. Build a dataset&quot;">​</a></h2><p><img src="'+i+'" alt="Choosing dataset images"></p><ol><li>Choose the <strong>Outfit set</strong>. A dataset covers one outfit set.</li><li>Enter a <strong>Name</strong> and a <strong>Character trigger</strong>: a word unique to this character (for example <code>lyra_vance</code>). It goes near the start of every caption and is added automatically when you generate. Fill in <strong>Outfit trigger</strong> too if the outfit should be learned separately.</li><li>Pick the images. All images of that character and outfit are listed with their gallery verdict (<strong>Adopted</strong>, <strong>Pass</strong>, <strong>Failed</strong>). Tick them one by one or use the buttons: <ul><li><strong>Adopted only</strong>: the adopted image of each expression.</li><li><strong>All passed images</strong>: every passed image.</li><li><strong>Clear selection</strong>: untick everything.</li></ul></li><li>Press <strong>Create dataset</strong>.</li></ol><h3 id="captions" tabindex="-1">Captions <a class="header-anchor" href="#captions" aria-label="Permalink to &quot;Captions&quot;">​</a></h3><p>Each image gets a caption automatically. The trigger, composition and expression tags stay; appearance and outfit tags are left out so that the trigger word learns them.</p><p><img src="'+n+'" alt="Automatic captions"></p><p>Edit captions directly and press <strong>Save edited captions</strong>. <strong>Rebuild automatic captions</strong> goes back to the automatic version.</p><h3 id="a-good-dataset" tabindex="-1">A good dataset <a class="header-anchor" href="#a-good-dataset" aria-label="Permalink to &quot;A good dataset&quot;">​</a></h3><ul><li><strong>Number of images</strong>: 25 or more is recommended. Around 15 can make the framing unstable.</li><li><strong>Square images</strong> (for example 1536×1536) are recommended. With one aspect ratio only, the LoRA learns that framing too.</li><li><strong>Varied expressions and poses</strong>: a single pose tends to get baked in.</li><li>Results are best when you generate with a model of the same family as the training base.</li></ul><h2 id="_2-training" tabindex="-1">2. Training <a class="header-anchor" href="#_2-training" aria-label="Permalink to &quot;2. Training&quot;">​</a></h2><p><img src="'+d+'" alt="Training settings"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Notes</th></tr></thead><tbody><tr><td>Dataset</td><td>The dataset from step 1.</td></tr><tr><td>Method</td><td><strong>T-LoRA</strong> (default, dim 32, alpha 32) or plain <strong>LoRA</strong> (dim 32, alpha 128).</td></tr><tr><td>Base model</td><td><strong>Official Anima base</strong> (default) or the <strong>generation model</strong> (an Anima fine-tune set in Settings).</td></tr><tr><td>Epochs</td><td>How many times the dataset is repeated. Default 40.</td></tr><tr><td>Save every (epochs)</td><td>Keeps a file at these epochs. With the default 10 you get e10, e20, e30 and e40.</td></tr><tr><td>Learning rate</td><td>Default 1e-4.</td></tr></tbody></table><p><strong>Start training</strong> runs preprocessing (resizing images, encoding captions) and then training; progress shows under <strong>Training runs</strong>. New images are not generated while a LoRA trains; queued jobs continue afterwards. The log is in <code>logs/lora/&lt;run name&gt;/trainer.log</code>.</p><p><img src="'+l+'" alt="Finished training"></p><h2 id="_3-register-and-apply-automatically" tabindex="-1">3. Register and apply automatically <a class="header-anchor" href="#_3-register-and-apply-automatically" aria-label="Permalink to &quot;3. Register and apply automatically&quot;">​</a></h2><p>When training ends, every saved epoch gets a <strong>Register eN</strong> button. Registered epochs appear in the <strong>Registered LoRAs</strong> tab.</p><p><img src="'+h+'" alt="Registered LoRAs"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Notes</th></tr></thead><tbody><tr><td>Auto apply</td><td>When on, the Jobs menu adds the LoRA and the trigger for this character.</td></tr><tr><td>Applies to</td><td>The whole character or one outfit set.</td></tr><tr><td>Scope</td><td>This character only, or global.</td></tr><tr><td>Strength</td><td>LoRA strength. Lower it if the framing drifts.</td></tr><tr><td>Model family</td><td>The model family this LoRA is for.</td></tr></tbody></table><p>Only one LoRA per character, outfit and model family can be applied automatically. Untick <strong>Apply registered LoRAs automatically</strong> in the Jobs menu to leave it out of one queueing. The &quot;Automatic LoRAs&quot; line of the Jobs preview shows whether it is applied.</p><h2 id="choosing-an-epoch" tabindex="-1">Choosing an epoch <a class="header-anchor" href="#choosing-an-epoch" aria-label="Permalink to &quot;Choosing an epoch&quot;">​</a></h2><p>Comparing epochs or strengths with the same seed makes the choice easy. Vary <strong>LoRA strength</strong> in the <a href="./lab">lab</a>, or register several epochs and generate with the same seed.</p><p>Below, the sample character trained on 30 square images for 40 epochs, with the LoRA off (top) and on (bottom) at the same seed. The chest emblem and striped tie from the dataset appear in every expression.</p><p><img src="'+e+'" alt="LoRA off and on"></p><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>LoRAs trained from Anima weights are Derivatives under the CircleStone Labs Non-Commercial License. See the <a href="https://github.com/kiritype/asset-studio#license" target="_blank" rel="noreferrer">README</a> for what that means when you share or sell them.</p>',28)])])}const R=a(g,[["render",p]]);export{A as __pageData,R as default};
